  3	export const ACCOUNT_SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1_000;
  4	const COOKIE_NAME = 'pokewar_account';
  5	
  6	export function createAccountSessionToken(): string {
  7	  return randomBytes(32).toString('base64url');
  8	}
  9	
 10	export function hashSessionToken(token: string): string {
 11	  return createHash('sha256').update(token).digest('hex');
 12	}
 13	
 14	export function serializeAccountCookie(
 15	  token: string,
 16	  secure: boolean,
 17	  maxAgeSeconds = ACCOUNT_SESSION_TTL_MS / 1_000,
 18	): string {
 19	  return [
 20	    `${COOKIE_NAME}=${token}`,
 21	    'Path=/',
 22	    'HttpOnly',
 23	    'SameSite=Lax',
 24	    `Max-Age=${String(maxAgeSeconds)}`,
 25	    ...(secure ? ['Secure'] : []),
 26	  ].join('; ');
 27	}
 28	
 29	export function accountTokenFromCookies(cookies: Readonly<Record<string, string>>): string | null {
 30	  return cookies[COOKIE_NAME] ?? null;
 31	}
  1	import { composePublicName, NAME_NOUNS, NAME_PREFIXES } from '@pokewar/protocol';
  2	import { createHmac, randomBytes, randomInt, timingSafeEqual } from 'node:crypto';
  3	
  4	const COOKIE_NAME = 'pokewar_guest';
  5	export const GUEST_IDENTITY_TTL_SECONDS = 30 * 24 * 60 * 60;
  6	
  7	export interface GuestIdentity {
  8	  readonly id: string;
  9	  readonly kind: 'guest' | 'account' | 'bot';
 10	  readonly nickname: string;
 11	  readonly displayName: string;
 12	}
 13	
 14	export interface GuestIdentityStore {
 15	  get(id: string): Promise<GuestIdentity | undefined>;
 16	  save(identity: GuestIdentity): Promise<void>;
 17	}
 18	
 19	export class MemoryGuestIdentityStore implements GuestIdentityStore {
 20	  readonly #identities = new Map<string, GuestIdentity>();
 21	
 22	  get(id: string): Promise<GuestIdentity | undefined> {
 23	    return Promise.resolve(this.#identities.get(id));
 24	  }
 25	
 26	  save(identity: GuestIdentity): Promise<void> {
 27	    this.#identities.set(identity.id, identity);
 28	    return Promise.resolve();
 29	  }
 30	}
 31	
 32	function signature(id: string, secret: string): string {
 33	  return createHmac('sha256', secret).update(id).digest('base64url');
 34	}
 35	
 36	function shortId(id: string): string {
 37	  return createHmac('sha256', 'pokewar-display-id')
 38	    .update(id)
 39	    .digest('base64url')
 40	    .slice(0, 4)
 41	    .toUpperCase();
 42	}
 43	
 44	export interface GuestIdentityInput {
 45	  readonly id?: string;
 46	  readonly prefixIndex?: number;
 47	  readonly nounIndex?: number;
 48	}
 49	
 50	export function createGuestIdentity(input: GuestIdentityInput = {}): GuestIdentity {
 51	  const id = input.id ?? randomBytes(18).toString('base64url');
 52	  const prefix = NAME_PREFIXES[input.prefixIndex ?? randomInt(NAME_PREFIXES.length)];
 53	  const noun = NAME_NOUNS[input.nounIndex ?? randomInt(NAME_NOUNS.length)];
 54	  if (!prefix || !noun) throw new Error('GUEST_NAME_INDEX_OUT_OF_RANGE');
 55	  const nickname = composePublicName(prefix, noun);
 56	  return { id, kind: 'guest', nickname, displayName: `${nickname}#${shortId(id)}` };
 57	}
 58	
 59	export function createBotIdentity(id: string): GuestIdentity {
 60	  const prefixIndex = randomInt(NAME_PREFIXES.length);
 61	  const nounIndex = randomInt(NAME_NOUNS.length);
 62	  const prefix = NAME_PREFIXES[prefixIndex];
 63	  const noun = NAME_NOUNS[nounIndex];
 64	  if (!prefix || !noun) throw new Error('BOT_NAME_INDEX_OUT_OF_RANGE');
 65	  const nickname = composePublicName(prefix, noun);
 66	  return { id, kind: 'bot', nickname, displayName: `${nickname} [机器人]` };
 67	}
 68	
 69	export function serializeGuestCookie(identityId: string, secret: string, secure: boolean): string {
 70	  const value = `${identityId}.${signature(identityId, secret)}`;
 71	  return [
 72	    `${COOKIE_NAME}=${value}`,
 73	    'Path=/',
 74	    'HttpOnly',
 75	    'SameSite=Lax',
 76	    `Max-Age=${String(GUEST_IDENTITY_TTL_SECONDS)}`,
 77	    ...(secure ? ['Secure'] : []),
 78	  ].join('; ');
 79	}
 80	
 81	export function parseCookies(header: string | undefined): Readonly<Record<string, string>> {
 82	  if (!header) return {};
 83	  return Object.fromEntries(
 84	    header.split(';').flatMap((part) => {
 85	      const separator = part.indexOf('=');
 86	      if (separator <= 0) return [];
 87	      return [[part.slice(0, separator).trim(), part.slice(separator + 1).trim()]];
 88	    }),
 89	  );
 90	}
 91	
 92	export function verifyGuestCookie(cookieHeader: string | undefined, secret: string): string | null {
 93	  const value = parseCookies(cookieHeader)[COOKIE_NAME];
 94	  if (!value) return null;
 95	  const separator = value.lastIndexOf('.');
 96	  if (separator <= 0) return null;
 97	  const id = value.slice(0, separator);
 98	  const received = value.slice(separator + 1);
 99	  const expected = signature(id, secret);
100	  const receivedBuffer = Buffer.from(received);
101	  const expectedBuffer = Buffer.from(expected);
102	  if (receivedBuffer.length !== expectedBuffer.length) return null;
103	  return timingSafeEqual(receivedBuffer, expectedBuffer) ? id : null;
104	}
  1	import { createClient, type RedisClientType } from 'redis';
  2	
  3	export interface RedisClients {
  4	  readonly command: RedisClientType;
  5	  readonly publisher: RedisClientType;
  6	  readonly subscriber: RedisClientType;
  7	  close(): Promise<void>;
  8	}
  9	
 10	export async function createRedisClients(url: string): Promise<RedisClients> {
 11	  const command = createClient({ url });
 12	  command.on('error', (error) => console.error('[redis:command]', error));
 13	  await command.connect();
 14	  const publisher = command.duplicate();
 15	  const subscriber = command.duplicate();
 16	  publisher.on('error', (error) => console.error('[redis:publisher]', error));
 17	  subscriber.on('error', (error) => console.error('[redis:subscriber]', error));
 18	  await Promise.all([publisher.connect(), subscriber.connect()]);
 19	  return {
 20	    command,
 21	    publisher,
 22	    subscriber,
 23	    async close() {
 24	      await Promise.all([
 25	        command.isOpen ? command.quit() : Promise.resolve(''),
 26	        publisher.isOpen ? publisher.quit() : Promise.resolve(''),
 27	        subscriber.isOpen ? subscriber.quit() : Promise.resolve(''),
 28	      ]);
 29	    },
 30	  };
 31	}
  1	import type { GameState } from '@pokewar/domain';
  2	import type { Pool } from 'pg';
  3	import {
  4	  REPLAY_RETENTION_MS,
  5	  type CompletedReplay,
  6	  type ReplayRepository,
  7	  type StoredReplay,
  8	} from './replayRepository.js';
  9	
 10	interface ReplayRow {
 11	  readonly room_id: string;
 12	  readonly finished_at: Date;
 13	  readonly replay_expires_at: Date;
 14	  readonly replay_payload: GameState;
 15	}
 16	
 17	export class PostgresReplayRepository implements ReplayRepository {
 18	  constructor(private readonly pool: Pool) {}
 19	
 20	  async save(replay: CompletedReplay): Promise<void> {
 21	    const finishedAt = new Date(replay.finishedAt);
 22	    const expiresAt = new Date(replay.finishedAt + REPLAY_RETENTION_MS);
 23	    await this.pool.query(
 24	      `INSERT INTO match_replays (
 25	        room_id, finished_at, replay_expires_at, winner_player_id,
 26	        participant_ids, summary, replay_payload
 27	      ) VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7::jsonb)
 28	      ON CONFLICT (room_id) DO UPDATE SET
 29	        finished_at = EXCLUDED.finished_at,
 30	        replay_expires_at = EXCLUDED.replay_expires_at,
 31	        winner_player_id = EXCLUDED.winner_player_id,
 32	        participant_ids = EXCLUDED.participant_ids,
 33	        summary = EXCLUDED.summary,
 34	        replay_payload = EXCLUDED.replay_payload`,
 35	      [
 36	        replay.roomId,
 37	        finishedAt,
 38	        expiresAt,
 39	        replay.winnerPlayerId,
 40	        [...replay.participantIds],
 41	        JSON.stringify(replay.summary),
 42	        JSON.stringify(replay.game),
 43	      ],
 44	    );
 45	  }
 46	
 47	  async getForParticipant(
 48	    roomId: string,
 49	    participantId: string,
 50	    now: number,
 51	  ): Promise<StoredReplay | null> {
 52	    const result = await this.pool.query<ReplayRow>(
 53	      `SELECT room_id, finished_at, replay_expires_at, replay_payload
 54	       FROM match_replays
 55	       WHERE room_id = $1
 56	         AND $2 = ANY(participant_ids)
 57	         AND replay_payload IS NOT NULL
 58	         AND replay_expires_at > $3`,
 59	      [roomId, participantId, new Date(now)],
 60	    );
 61	    const row = result.rows[0];
 62	    return row
 63	      ? {
 64	          roomId: row.room_id,
 65	          finishedAt: row.finished_at.getTime(),
 66	          expiresAt: row.replay_expires_at.getTime(),
 67	          game: row.replay_payload,
 68	        }
 69	      : null;
 70	  }
 71	
 72	  async purgeExpired(now: number): Promise<number> {
 73	    const result = await this.pool.query(
 74	      `UPDATE match_replays
 75	       SET replay_payload = NULL,
 76	           participant_ids = ARRAY[]::text[],
 77	           purged_at = $1
 78	       WHERE replay_payload IS NOT NULL
 79	         AND replay_expires_at <= $1`,
 80	      [new Date(now)],
 81	    );
 82	    return result.rowCount ?? 0;
 83	  }
 84	
 85	  async close(): Promise<void> {
 86	    await this.pool.end();
 87	  }
 88	}

