 72	  async purgeExpired(now: number): Promise<number> {
 73	    const result = await this.pool.query(
 74	      `UPDATE match_replays
 75	       SET replay_payload = NULL,
 76	           participant_ids = ARRAY[]::text[],
 77	           purged_at = $1
 78	       WHERE replay_payload IS NOT NULL
 79	         AND replay_expires_at <= $1`,
 80	      [new Date(now)],
 81	    );
 82	    return result.rowCount ?? 0;
 83	  }
